alter table public.audit_events add column if not exists correlation_id text; alter table public.audit_events add column if not exists before_state jsonb; alter table public.audit_events add column if not exists after_state jsonb; alter table public.audit_events add column if not exists reason text; create index if not exists audit_events_correlation_idx on public.audit_events(correlation_id); create table if not exists public.discovery_permission_evidence (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.discovery_sources(id) on delete cascade, evidence_type text not null, evidence_url text, evidence_text text, verified_at timestamptz, expires_at timestamptz, owner_id text, status text not null default 'pending', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create unique index if not exists discovery_permission_active_idx on public.discovery_permission_evidence(source_id, evidence_type) where status in ('verified','approved'); alter table public.discovery_permission_evidence enable row level security; do $$ begin if not exists (select 1 from pg_policies where schemaname='public' and tablename='discovery_permission_evidence' and policyname='deny_discovery_permission_evidence_anon') then create policy deny_discovery_permission_evidence_anon on public.discovery_permission_evidence for all to anon using (false) with check (false); end if; if not exists (select 1 from pg_policies where schemaname='public' and tablename='discovery_permission_evidence' and policyname='deny_discovery_permission_evidence_auth') then create policy deny_discovery_permission_evidence_auth on public.discovery_permission_evidence for all to authenticated using (false) with check (false); end if; end $$; create or replace function public.audit_event_append_only_guard() returns trigger language plpgsql as $$ begin raise exception 'audit_events_append_only'; end; $$; drop trigger if exists audit_events_append_only_guard on public.audit_events; create trigger audit_events_append_only_guard before update or delete on public.audit_events for each row execute function public.audit_event_append_only_guard();
